import {icon} from './icons.js';
import {domainLinks as links,domainCategories as categories,states,institutionTypes,requiredDocuments,domainFaqs,validateDomainLabel,validateLocalPDF} from './domain-data.js?v=a85ff678206c';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,text,cls='dr-link')=>`<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${text}${icon('external')}</a>`;
const steps=['Check Eligibility','Select Domain','Institution Details','Upload Documents','Review Application','Submit Application','Track Application'];
const info=(text,cls='')=>`<div class="dr-notice ${cls}">${icon('file')}<div>${text}</div></div>`;
const networkArt=()=>`<svg class="dr-network-art" viewBox="0 0 560 240" aria-hidden="true"><defs><radialGradient id="networkGlow"><stop stop-color="#065cf6" stop-opacity=".4"/><stop offset="1" stop-color="#07294e" stop-opacity="0"/></radialGradient></defs><ellipse cx="340" cy="120" rx="230" ry="170" fill="url(#networkGlow)"/><g stroke="#5fb9ff" fill="none" opacity=".5"><ellipse cx="345" cy="120" rx="175" ry="150"/><ellipse cx="345" cy="120" rx="115" ry="150"/><ellipse cx="345" cy="120" rx="48" ry="150"/><path d="M170 120h350M190 50h310M190 190h310M345-30v300M110 200 250 22 410 212 520 45 170 120 470 82 310 230 250 22 345 120 520 155 410 212 110 200"/></g><g fill="#caefff">${[[170,120],[250,22],[345,120],[410,212],[520,45],[470,82],[310,230],[190,50],[190,190],[500,190],[520,155],[280,75],[110,200]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}</g></svg>`;
const laptop=()=>`<div class="dr-illustration" aria-hidden="true"><div class="dr-institute">${icon('building')}</div><div class="dr-laptop"><div><span id="dr-art-label">.ac.in</span></div><i></i><b>${icon('check')}</b></div><small>Your institution.<br>Your digital identity.</small></div>`;
export function domainRegistrationPage(){return `<div class="domain-page"><section class="dr-hero"><div class="container dr-hero-inner"><div><div class="dr-eyebrow">INSTITUTIONAL DOMAIN SERVICES</div><h1>Domain Registration</h1><p>Build your institution’s digital identity. <br>Prepare an application for education and research domains.</p><div class="button-row">${external(links.guidelines,icon('book')+'View Registration Guidelines','button')}${external(links.portal,'Go to Official Portal','button secondary')}</div></div>${networkArt()}</div></section><div class="container dr-workspace"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a>${icon('arrow')}<a href="/services">Services</a>${icon('arrow')}<span aria-current="page">Domain Registration</span></nav>${info('<strong>Prepare here. Register with ERNET.</strong> This independent preparation workspace does not submit applications. Eligibility and approval are decided by ERNET India.','dr-top-notice')}<ol class="dr-stepper" aria-label="Registration progress" id="dr-stepper"></ol><div class="dr-layout"><aside class="dr-sidebar"><div class="dr-category-card"><h2>${icon('network')}Domain Categories</h2><label class="dr-search-label" for="dr-category-search">Find a category</label><div class="dr-search">${icon('search')}<input id="dr-category-search" type="search" placeholder="Search categories…" autocomplete="off"></div><div id="dr-categories"></div><p class="dr-category-foot">8 official categories<br><a href="#dr-help">Choosing a domain? Get help ↓</a></p></div><div class="dr-private-note">${icon('shield')}<p><strong>Your draft stays with you.</strong><br>Details and files stay in this tab. Refreshing or leaving clears them.</p></div></aside><section class="dr-panel" aria-labelledby="dr-panel-title"><div id="dr-stage"></div></section></div><div class="dr-assurances">${[['shield','Private preparation','Files stay in your browser'],['phone','Institutional support','Official ERNET helpdesk'],['file','Verified guidelines','Policy effective 25 Aug 2025'],['users','Education & research','Designed for institutions']].map(([i,h,p])=>`<div>${icon(i)}<span><strong>${h}</strong><small>${p}</small></span></div>`).join('')}</div><section class="dr-resources" aria-labelledby="dr-existing-title"><div class="dr-section-heading"><div><span class="dr-eyebrow">ALREADY HAVE A DOMAIN?</span><h2 id="dr-existing-title">Manage your institution’s domain</h2></div>${external(links.login,'Open official domain panel')}</div><div class="dr-resource-grid"><article>${icon('clock')}<h3>Renew & track</h3><p>Sign in to view real application status, requested corrections and renewal options. Renew before expiry with fresh required documents.</p>${external(links.login,'Sign in to ERNET')}</article><article>${icon('network')}<h3>DNS & record updates</h3><p>Manage nameservers and institutional contacts through the authorized panel. Registration needs at least two valid nameservers.</p>${external(links.help,'Read the process guide')}</article><article>${icon('file')}<h3>Fees & payments</h3><p>Confirm category, duration and GST on the current registration tariff. Payments are accepted through the official domain panel gateway.</p>${external(links.tariff,'View official registration tariff')}</article></div></section><section id="dr-help" class="dr-help"><div><span class="dr-eyebrow">GUIDANCE AT EVERY STEP</span><h2>Questions before you apply?</h2><label for="dr-faq-search" class="dr-search-label">Search frequently asked questions</label><div class="dr-search">${icon('search')}<input type="search" id="dr-faq-search" placeholder="Try documents, renewal or DNS…"></div><div class="dr-faq" id="dr-faq"></div></div><aside class="dr-support"><div class="iconbox">${icon('phone')}</div><h3>Domain registration helpdesk</h3><p>Email first to open a support ticket. Keep the ticket number ready when you call.</p><a href="mailto:helpdesk@domain.ernet.in">helpdesk@domain.ernet.in</a><a href="tel:+911122170580">011-22170580</a><a href="tel:+911122170594">011-22170594</a><p>Monday–Friday<br>9:30 AM–5:00 PM</p>${external(links.support,'Official contact information')}<hr><p><strong>Policy reference</strong><br>Checked 24 October 2026. Current official requirements take precedence.</p>${external(links.guidelines,'Guidelines & terms')}</aside></section><div class="dr-bottom"><a href="/portals">← Back to service portals</a><button type="button" class="dr-text-button" id="dr-clear">Clear preparation draft</button></div></div><dialog class="dr-dialog" id="dr-category-dialog" aria-labelledby="dr-dialog-title"><div id="dr-dialog-content"></div></dialog></div>`;}

export function bindDomainRegistration(){
 const root=document.querySelector('.domain-page');if(!root)return;
 let current=0, completed=-1, chosen=categories[0], pending=null, busy=0, revision=0;
 let data={category:chosen.id}, files=new Map(), fileErrors=new Map(), fileVersions=new Map();
 const stage=root.querySelector('#dr-stage'),stepper=root.querySelector('#dr-stepper'),dialog=root.querySelector('#dr-category-dialog');
 const value=name=>esc(data[name]||'');
 const checked=name=>data[name]?' checked':'';
 const field=(name,label,opts={})=>`<div class="dr-field ${opts.wide?'dr-wide':''}"><label for="dr-${name}">${label}${opts.required?'<span aria-hidden="true"> *</span>':''}</label><input id="dr-${name}" name="${name}" type="${opts.type||'text'}" value="${value(name)}" ${opts.required?'required':''} ${opts.pattern?`pattern="${opts.pattern}"`:''} ${opts.maxlength?`maxlength="${opts.maxlength}"`:'maxlength="200"'} ${opts.placeholder?`placeholder="${opts.placeholder}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:'autocomplete="off"'}>${opts.hint?`<small>${opts.hint}</small>`:''}</div>`;
 const select=(name,label,options,required=true)=>`<div class="dr-field"><label for="dr-${name}">${label}${required?'<span aria-hidden="true"> *</span>':''}</label><select id="dr-${name}" name="${name}" ${required?'required':''}><option value="">Select ${label.toLowerCase()}</option>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${data[name]===v?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`;
 const check=(name,label,required=true)=>`<label class="dr-checkbox"><input type="checkbox" name="${name}" ${checked(name)} ${required?'required':''}><span>${label}${required?' <span aria-hidden="true">*</span>':''}</span></label>`;
 const panelHead=(title,desc)=>`<div class="dr-panel-heading"><span class="dr-step-caption">STEP ${current+1} OF 7 · ${current<5?'LOCAL PREPARATION':'OFFICIAL PORTAL'}</span><h2 id="dr-panel-title" tabindex="-1">${icon(current===3?'file':current===4?'check':current>4?'external':'shield')}${title}</h2><p>${desc}</p></div>`;
 const actions=(label)=>`<div id="dr-form-message" role="status" aria-live="polite"></div><div class="dr-actions">${current?'<button type="button" class="button secondary" data-back>← Back</button>':''}<button type="submit" class="button">${label}${icon('arrow')}</button></div>`;
 const categoryPolicy=c=>`<p>${esc(c.description)}</p><p>All categories require an eligible institution in India and relevant recognition, affiliation or registration evidence. Category selection alone does not establish eligibility.</p><ul><li>Use the institution’s full name or abbreviation; avoid generic, personal, reserved or misleading names.</li><li>${c.idn?'IDN script and naming eligibility must be checked on the official portal.':'ASCII labels: 3–63 letters, digits or hyphens; no leading or trailing hyphen.'}</li><li>${c.research?'Research mandate evidence is additionally required.':'Supporting documents depend on institutional status.'} Government schools have a specific three-document checklist.</li></ul>${external(links.guidelines,'Read applicable eligibility and naming rules')}`;
 function renderCategories(q=''){const shown=categories.filter(c=>(c.id+' '+c.title).toLowerCase().includes(q.toLowerCase()));root.querySelector('#dr-categories').innerHTML=shown.length?shown.map(c=>`<button type="button" class="dr-category ${chosen.id===c.id?'selected':''}" data-category="${c.id}" aria-pressed="${chosen.id===c.id}"><span><strong>.${c.id}</strong><small>${c.title}</small></span>${icon('arrow')}</button>`).join(''):'<p class="dr-no-results">No categories found.</p>';}
 function renderStepper(){stepper.innerHTML=steps.map((s,i)=>`<li class="${i===current?'current':''} ${i<=completed&&i<5?'complete':''} ${i>4?'external-step':''}"><button type="button" data-step="${i}" ${i>Math.min(completed+1,5)&&!(i===6&&current===6)?'disabled':''} ${i===current?'aria-current="step"':''} aria-label="Step ${i+1}: ${s}${i<=completed&&i<5?', preparation complete':''}"><span>${i<=completed&&i<5?icon('check'):i+1}</span><strong>${s}</strong>${i>4?'<small>On official portal</small>':''}</button></li>`).join('');}
 function render(focus=true){renderStepper();
 if(current===0){stage.innerHTML=panelHead('Eligibility Checker','Choose your institution’s category and check the published requirements.')+`<form id="dr-form" novalidate><div class="dr-eligibility-layout"><div><div class="dr-form-grid">${select('category','Domain category',categories.map(c=>[c.id,'.'+c.id]))}${select('institutionType','Institution type',institutionTypes)}${select('state','State / UT',states)}</div><details class="dr-policy" open><summary>Requirements for .${chosen.id}</summary>${categoryPolicy(chosen)}</details><div class="dr-form-grid">${select('recognition','Recognition / legal status',[['recognized','Recognized / affiliated / legally registered'],['uncertain','Not sure — need official guidance'],['none','No recognition or registration evidence']])}${chosen.research?select('researchEvidence','Research mandate evidence',[['yes','Available'],['no','Not available / unsure']]):''}</div>${check('inIndia','The institution is situated in India.')}${check('authority','I am authorized to prepare this information for the institution.')}${info('This is a <strong>preliminary eligibility check</strong>. ERNET verifies institutional documents and decides acceptance.')}<div id="dr-eligibility-result" role="status"></div>${actions('Check Eligibility')}</div>${laptop()}</div></form>`;
 }else if(current===1){stage.innerHTML=panelHead('Choose your domain','Start with a name that reflects your institution.')+`<form id="dr-form" novalidate><div class="dr-category-chip">${icon('globe')} Selected category <strong>.${chosen.id}</strong><button type="button" class="dr-text-button" data-edit="0">Change</button></div>${field('domainLabel','Desired domain name',{required:true,maxlength:63,placeholder:chosen.idn?'संस्थान':'institution-name',hint:'Enter only the name before .'+chosen.id+'. Do not include www or the extension.'})}<div class="dr-domain-preview"><small>PROPOSED DOMAIN</small><strong id="dr-domain-preview">${esc(data.domainLabel||'your-institution')}.${chosen.id}</strong><span id="dr-format-status" role="status">Enter a name to check its format.</span></div><div class="dr-status-row"><span>Format: <b id="dr-format-badge">Not checked</b></span><span>Availability: <b>Not verified</b></span><span>Approval: <b>Not requested</b></span></div>${check('nameMatches','The name matches the institution’s full name or abbreviation.')}${check('nameRestricted','I have reviewed the restrictions on generic, personal, reserved and misleading names.')}${info('These acknowledgements do not validate reserved names or confer approval. '+external(links.portal,'Check live availability on the official portal'))}${actions('Continue to Institution Details')}</form>`;
 }else if(current===2){stage.innerHTML=panelHead('Institution & contact details','Prepare the institutional information used in the official registration process.')+`<form id="dr-form" novalidate>${info('Preparation draft only. Enter only the information you want to keep in this tab; nothing is transmitted or saved by this site.')}<fieldset><legend>Institutional information</legend><div class="dr-form-grid">${field('institutionName','Official institution name',{required:true,wide:true})}${field('address','Postal address',{required:true,wide:true})}${field('city','City / town',{required:true})}${select('state','State / UT',states)}${field('postalCode','PIN code',{required:true,pattern:'[1-9][0-9]{5}',maxlength:6,hint:'Six-digit Indian postal code.'})}${field('institutionPhone','Institutional telephone',{type:'tel',pattern:'[+0-9 ()-]{8,20}',hint:'Optional in this preparation draft.'})}${field('website','Existing website',{type:'url',placeholder:'https://',hint:'Optional, if available.'})}</div></fieldset>${['head','admin','technical','billing'].map((kind,i)=>`<fieldset><legend>${['Head of Institution','Administrative contact','Technical contact','Billing contact'][i]}</legend>${i?`<button type="button" class="dr-copy" data-copy="${kind}">Use Head of Institution details</button>`:''}${kind==='admin'?'<p class="dr-field-note">The administrative contact must belong to the applying institution. Prepare their appointment evidence.</p>':''}<div class="dr-form-grid">${field(kind+'Name','Full name',{required:true})}${field(kind+'Designation','Designation',{required:true})}${field(kind+'Email','Official email',{type:'email',required:true})}${field(kind+'Phone','Contact number',{type:'tel',required:true,pattern:'[+0-9 ()-]{8,20}',hint:'8–20 characters: digits, +, spaces, parentheses or hyphens.'})}</div></fieldset>`).join('')}<fieldset><legend>Documents that apply to your institution</legend><div class="dr-form-grid">${select('translation','Affiliation document language',[['no','Hindi or English'],['yes','Another language — translation required']])}${select('gst','GST evidence',[['none','Not applicable / no GST number supplied'],['institution','Institution’s GST number will be supplied'],['parent','Parent society / trust GST number will be supplied']])}</div></fieldset><fieldset><legend>DNS preparation</legend><p class="dr-field-note">At least two valid nameservers and DNS entries are required for the domain to resolve. This page never changes DNS.</p>${select('dnsPlan','Nameserver arrangement',[['ernet','Use ERNET DNS — confirm in official panel'],['own','Use institutional / hosting-provider nameservers'],['later','Confirm with technical contact before official submission']])}<div id="dr-nameservers" ${data.dnsPlan!=='own'?'hidden':''}><div class="dr-form-grid">${field('ns1','Primary nameserver',{required:data.dnsPlan==='own',placeholder:'ns1.provider.example'})}${field('ns2','Secondary nameserver',{required:data.dnsPlan==='own',placeholder:'ns2.provider.example'})}</div></div>${external(links.guidelines,'Read official DNS requirements')}</fieldset>${actions('Continue to Documents')}</form>`;
 }else if(current===3){const docs=requiredDocuments(data,chosen);stage.innerHTML=panelHead('Document readiness','Select the applicable PDFs for a local file check. No upload takes place.')+info('<strong>PDF only · maximum 2 MB per file.</strong> Documents must be attested by the Head of Institution. File checks here examine size and PDF markers; they do not verify authenticity or scan for malware.')+`<form id="dr-form" novalidate><div class="dr-documents">${docs.map(d=>`<div class="dr-document"><div class="dr-document-title">${icon('file')}<div><h3>${d.name}</h3><p>${d.why}</p>${d.url?external(d.url,'Official template PDF'):''}</div></div><div class="dr-file-controls"><label class="dr-file-label" for="file-${d.id}">Select PDF<input type="file" id="file-${d.id}" data-document="${d.id}" accept="application/pdf,.pdf" aria-describedby="status-${d.id}"></label><div class="dr-file-status" id="status-${d.id}" role="status">${fileStatus(d.id)}</div></div></div>`).join('')}</div>${data.institutionType!=='Government school'?info('The official guidelines also require true copies of the original ₹100 undertaking within 15 days of online submission. Check the official postal instructions.'):''}${check('documentAttestation','The selected documents are the applicable, authentic copies attested by the institution head.')}${actions('Review Application')}</form>`;
 }else if(current===4){stage.innerHTML=panelHead('Review your preparation','Check each section before continuing to the official application process.')+info('<strong>Draft review only.</strong> Availability, document acceptance and official approval have not been verified.')+review()+`<form id="dr-form" novalidate><fieldset><legend>Preparation declarations</legend><p class="dr-field-note">These acknowledgements are for this local draft. Complete the registrar’s actual declarations and Annexure I on the official portal.</p>${check('accurate','I have checked that the information in this preparation draft is accurate.')}${check('authorized','I am authorized to act for the institution and have reviewed its eligibility evidence.')}${check('authentic','The supporting documents are authentic and meet the applicable attestation requirements.')}${check('readGuidelines','I have reviewed the '+external(links.guidelines,'official guidelines and terms')+'.')}${check('understand','I understand that nothing has been sent to ERNET and that I must complete the official registration process.')}</fieldset>${actions('Continue to Submission')}</form>`;
 }else if(current===5){stage.innerHTML=panelHead('Submit on the official portal','Your preparation is complete. Registration takes place in your ERNET account.')+`<div class="dr-handoff"><div class="dr-handoff-icon">${icon('external')}</div><h3>Ready for the next step</h3><p><strong>${esc(data.domainLabel)}.${chosen.id}</strong></p><p>This draft has not been submitted. The official portal will check availability, collect its required information and documents, take payment, and provide the actual application status.</p><ol><li>Open the official portal and search for the domain.</li><li>Sign in or follow the portal’s account creation process.</li><li>Complete the official application, payment and document steps.</li></ol><p class="dr-field-note">Nothing from this page is transferred automatically. Do not send documents or payments to this replica.</p><div class="dr-actions">${external(links.portal,'Submit Domain Registration Application','button dr-submit-official')}<button type="button" class="button secondary" id="dr-download">${icon('download')}Download preparation draft</button></div><p class="dr-field-note">The download contains entered details and file names; PDF contents are excluded.</p></div><div class="dr-actions"><button type="button" class="button secondary" data-back>← Back to Review</button><button type="button" class="dr-text-button" id="dr-track">Already applied? Track on official portal →</button></div>`;
 }else{stage.innerHTML=panelHead('Track through your ERNET account','View actual application progress securely in the official domain panel.')+`<div class="dr-handoff"><div class="dr-handoff-icon">${icon('shield')}</div><h3>No official status is available here</h3><p>Opening the official portal does not confirm submission. This page has no ERNET application reference, approval or payment record.</p>${external(links.login,'Sign in to track your application','button')}<p style="margin-top:20px">For requested corrections, sign in to your account. For help, email <a href="mailto:helpdesk@domain.ernet.in">helpdesk@domain.ernet.in</a> and quote your official ticket number.</p></div><div class="dr-actions"><button type="button" class="button secondary" data-back>← Back to Submission</button><button type="button" class="dr-text-button" id="dr-download">Download preparation draft</button></div>`;}
 const art=stage.querySelector('#dr-art-label');if(art)art.textContent='.'+chosen.id;
 stage.querySelector('#dr-form')?.addEventListener('submit',submit);
 if(current===1)updateDomain();
 if(focus)stage.querySelector('#dr-panel-title').focus({preventScroll:true});
 }
 function review(){const row=(k,v)=>`<div><dt>${k}</dt><dd>${esc(v||'Not supplied')}</dd></div>`;const section=(i,h,body)=>`<section class="dr-review-section"><h3>${h}<button type="button" data-edit="${i}" class="dr-text-button">Edit<span class="sr-only"> ${h}</span></button></h3>${body}</section>`;return section(0,'Eligibility',`<dl>${row('Category','.'+chosen.id)}${row('Institution type',data.institutionType)}${row('State / UT',data.state)}${row('Recognition',data.recognition==='recognized'?'Recognition / affiliation / legal registration confirmed':'Needs verification')}${row('In India / authorized',data.inIndia&&data.authority?'Acknowledged':'Missing')}${chosen.research?row('Research evidence',data.researchEvidence):''}</dl>`)+section(1,'Proposed domain',`<dl>${row('Domain',data.domainLabel+'.'+chosen.id)}${row('Format',chosen.idn?'Basic IDN syntax checked; official script validation pending':'ASCII format valid')}${row('Naming restrictions','Applicant acknowledged; registrar verification pending')}${row('Availability / approval','Not verified / not requested')}</dl>`)+section(2,'Institution & contacts',`<dl>${row('Institution',data.institutionName)}${row('Address',[data.address,data.city,data.state,data.postalCode].filter(Boolean).join(', '))}${row('Telephone',data.institutionPhone)}${row('Website',data.website)}${['head','admin','technical','billing'].map((k,i)=>row(['Head','Administrative','Technical','Billing'][i],[data[k+'Name'],data[k+'Designation'],data[k+'Email'],data[k+'Phone']].filter(Boolean).join(' · '))).join('')}${row('DNS arrangement',data.dnsPlan==='own'?[data.ns1,data.ns2].join(' · '):data.dnsPlan==='ernet'?'ERNET DNS — confirm on official portal':'Confirm before official submission')}${row('GST evidence',data.gst==='none'?'Not applicable':data.gst==='parent'?'Parent entity':'Institution')}${row('Translation needed',data.translation==='yes'?'Yes':'No')}</dl>`)+section(3,'Document readiness',`<ul class="dr-review-files">${requiredDocuments(data,chosen).map(d=>`<li>${icon('check')}<span><strong>${d.name}</strong><small>${esc(files.get(d.id)?.name||'Missing')} · local PDF check only</small></span></li>`).join('')}</ul>`);}
 function fileStatus(id){if(fileErrors.has(id))return `<span class="dr-error">${esc(fileErrors.get(id))}</span>`;const f=files.get(id);return f?`<span class="dr-file-ok">${icon('check')}${esc(f.name)} · ${Math.ceil(f.size/1024)} KB<br>Local check passed · not uploaded</span><button type="button" class="dr-text-button" data-remove="${id}">Remove<span class="sr-only"> ${esc(f.name)}</span></button>`:'<span>No file selected · PDF, up to 2 MB</span>';}
 function collect(form){for(const el of form.elements){if(!el.name)continue;data[el.name]=el.type==='checkbox'?el.checked:el.value.trim();}}
 function invalidate(step){completed=Math.min(completed,step-1);if(step<4)for(const key of ['accurate','authorized','authentic','readGuidelines','understand'])data[key]=false;renderStepper();}
 function error(text,el){const box=stage.querySelector('#dr-form-message');if(box){box.className='dr-error-summary';box.textContent=text;}if(el){el.setAttribute('aria-invalid','true');el.focus();}}
 function updateDomain(){const result=validateDomainLabel(data.domainLabel||'',chosen);stage.querySelector('#dr-domain-preview').textContent=(data.domainLabel||'your-institution')+'.'+chosen.id;stage.querySelector('#dr-format-status').textContent=result.message;stage.querySelector('#dr-format-badge').textContent=result.valid?(chosen.idn?'Basic IDN check passed':'Valid'):'Needs checking';}
 function submit(ev){ev.preventDefault();const form=ev.currentTarget;collect(form);form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));if(!form.checkValidity()){const invalid=form.querySelector(':invalid');error('Please complete the required fields and correct the highlighted value.',invalid);form.reportValidity();return;}
  if(current===0){if(data.recognition!=='recognized'||chosen.research&&data.researchEvidence!=='yes'){error('We cannot confirm preliminary eligibility with these answers. Review the official guidelines or contact the registry helpdesk.',form.querySelector(data.recognition!=='recognized'?'[name=recognition]':'[name=researchEvidence]'));return;}completed=0;renderStepper();stage.querySelector('#dr-eligibility-result').innerHTML=`<div class="dr-success"><strong>Preliminary check passed</strong><p>Your answers align with the broad published requirements. ERNET must still verify the institution and documents.</p><button type="button" class="button" data-continue-domain>Continue to Select Domain ${icon('arrow')}</button></div>`;stage.querySelector('[data-continue-domain]').focus();return;}
  if(current===1){const result=validateDomainLabel(data.domainLabel,chosen);if(!result.valid){error(result.message,form.querySelector('[name=domainLabel]'));return;}data.domainLabel=result.label;}
  if(current===2&&data.dnsPlan==='own'){const host=/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i;const bad=['ns1','ns2'].find(k=>!host.test(data[k]||''));if(bad||data.ns1.toLowerCase()===data.ns2.toLowerCase()){error('Enter two different valid nameserver hostnames (without https:// or paths).',form.querySelector('[name='+ (bad||'ns2')+']'));return;}}
  if(current===3){if(busy){error('Please wait for the local file check to finish.');return;}const missing=requiredDocuments(data,chosen).find(d=>!files.has(d.id)||fileErrors.has(d.id));if(missing){error('Select a valid PDF for '+missing.name+'.',form.querySelector('#file-'+missing.id));return;}}
  if(current===4&&completed<3){error('A preparation section changed. Complete its checks again before continuing.');return;}
  completed=current;current++;render();stage.scrollIntoView({block:'start',behavior:'auto'});
 }
 root.addEventListener('input',ev=>{const el=ev.target;if(el.id==='dr-category-search'){renderCategories(el.value);return;}if(el.id==='dr-faq-search'){renderFaq(el.value);return;}if(el.name&&el.type!=='file'&&el.name!=='category'){data[el.name]=el.type==='checkbox'?el.checked:el.value;invalidate(current);if(current===1)updateDomain();if(current===0)stage.querySelector('#dr-eligibility-result').innerHTML='';}});
 root.addEventListener('change',async ev=>{const el=ev.target;
  if(el.name==='category'){previewCategory(el.value);el.value=chosen.id;return;}
  if(el.name){data[el.name]=el.type==='checkbox'?el.checked:el.value;invalidate(current);if(current===0&&el.name==='institutionType') {files.clear();fileErrors.clear();revision++;}if(current===0&&['institutionType'].includes(el.name))render(false);if(el.name==='dnsPlan'){const wrap=stage.querySelector('#dr-nameservers');wrap.hidden=el.value!=='own';wrap.querySelectorAll('input').forEach(i=>i.required=el.value==='own');}if(['gst','translation'].includes(el.name)){files.clear();fileErrors.clear();revision++;}}
  if(el.dataset.document){const id=el.dataset.document,file=el.files?.[0];if(!file)return;invalidate(3);files.delete(id);fileErrors.delete(id);const token=Symbol(id), generation=revision;fileVersions.set(id,token);busy++;const status=root.querySelector('#status-'+id);status.textContent='Checking PDF locally…';el.disabled=true;try {const problem=await validateLocalPDF(file);if(token===fileVersions.get(id)&&generation===revision){if(problem)fileErrors.set(id,problem);else files.set(id,{name:file.name,size:file.size});}}catch{if(token===fileVersions.get(id)&&generation===revision)fileErrors.set(id,'Unable to read this file. Please select it again.');}finally{busy--;el.disabled=false;if(token===fileVersions.get(id)&&generation===revision)status.innerHTML=fileStatus(id);el.value='';}}
 });
 function previewCategory(id){pending=categories.find(c=>c.id===id);if(!pending)return;root.querySelector('#dr-dialog-content').innerHTML=`<div class="dr-dialog-top"><span class="dr-eyebrow">CATEGORY REQUIREMENTS</span><button type="button" class="dr-close" data-close aria-label="Close category requirements">${icon('close')}</button></div><h2 id="dr-dialog-title">.${pending.id}</h2><h3>${pending.title}</h3>${categoryPolicy(pending)}<h3>Documents to prepare</h3><p>Application letter, undertaking, admin appointment, recognition and legal registration evidence, plus applicable GST / translation documents. Government schools use the specific school checklist.${pending.research?' Research evidence is also required.':''}</p>${completed>=0&&pending.id!==chosen.id?'<p class="dr-error">Changing category clears completed checks and selected documents. Your institution details remain in this tab.</p>':''}<div class="dr-actions"><button type="button" class="button" data-use-category>Use .${pending.id}</button><button type="button" class="button secondary" data-close>Cancel</button></div>`;dialog.showModal();}
 root.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;
  if(b.dataset.category)previewCategory(b.dataset.category);
  if(b.hasAttribute('data-close'))dialog.close();
  if(b.hasAttribute('data-use-category')){if(pending.id!==chosen.id){chosen=pending;data.category=chosen.id;data.domainLabel='';data.nameMatches=false;data.nameRestricted=false;data.researchEvidence='';files.clear();fileErrors.clear();revision++;invalidate(0);current=0;}dialog.close();renderCategories(root.querySelector('#dr-category-search').value);render();}
  if(b.hasAttribute('data-continue-domain')){current=1;render();}
  if(b.dataset.step!==undefined){const n=Number(b.dataset.step);if(n<=Math.min(completed+1,5)||n===6&&current===6){current=n;render();}}
  if(b.dataset.edit!==undefined){current=Number(b.dataset.edit);render();}
  if(b.hasAttribute('data-back')){current=Math.max(0,current-1);render();}
  if(b.dataset.copy){collect(stage.querySelector('form'));for(const suffix of ['Name','Designation','Email','Phone'])data[b.dataset.copy+suffix]=data['head'+suffix]||'';invalidate(2);render(false);stage.querySelector('[name='+b.dataset.copy+'Name]').focus();}
  if(b.dataset.remove){const id=b.dataset.remove;files.delete(id);fileErrors.delete(id);invalidate(3);fileVersions.delete(id);root.querySelector('#status-'+id).innerHTML=fileStatus(id);root.querySelector('#file-'+id).focus();}
  if(b.classList.contains('dr-submit-official')||b.id==='dr-track'){current=6;render();}
  if(b.id==='dr-download')downloadDraft();
  if(b.id==='dr-clear'&&confirm('Clear all preparation details and selected file names from this tab?')){data={category:'ac.in'};chosen=categories[0];files.clear();fileErrors.clear();revision++;completed=-1;current=0;renderCategories();render();stage.scrollIntoView({block:'start'});}
 });
 function downloadDraft(){const payload={notice:'LOCAL PREPARATION DRAFT — NOT SUBMITTED TO ERNET. No availability, payment or approval is verified.',preparedAt:new Date().toISOString(),officialPortal:links.portal,data,documents:requiredDocuments(data,chosen).map(d=>({document:d.name,...files.get(d.id),status:files.has(d.id)?'local file check only':'not selected'}))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ernet-domain-preparation-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function renderFaq(q=''){const found=domainFaqs.filter(f=>(f[0]+' '+f[1]).toLowerCase().includes(q.toLowerCase()));root.querySelector('#dr-faq').innerHTML=found.length?found.map(([question,answer,url])=>`<details><summary>${question}</summary><p>${answer}</p>${external(url,'Official guidance')}</details>`).join(''):'<p role="status">No matching answers. Try another keyword or contact the helpdesk.</p>';}
 renderCategories();renderFaq();render(false);
}
